import React, { useState, useMemo } from 'react';
import { Avatar } from 'antd';
import { capitalize } from 'lodash';
import styled from 'styled-components';

import randomColor from 'components/common/randomColor';

const UserColumnWrap = styled(Avatar)`
  color: ${({ picture }) => (picture ? '' : '#FFFFFF')} !important;
  background-color: ${({ picture, color }) => (picture ? '' : color)};
  border-radius: ${({ shape }) => (shape === 'circle' ? '50%' : '6px')};
  min-width: ${({ size }) => size}px;
`;

const TextWrapper = styled.strong`
  color: #FFFFFF !important;
  font-weight: inherit;
`;

const UserImageInfo = ({ picture, nameInfo, size, shape, className }) => {
  const [imageError, setImageError] = useState(false);
  const firstChar = nameInfo?.charAt(0);

  const handleImageError = () => {
    setImageError(true);
  };
  const color = useMemo(()=> nameInfo && randomColor(nameInfo), [nameInfo]) ;

  const textCapital = useMemo(() => capitalize(firstChar), [firstChar]);

  return (
    <>
      {imageError && (
        <UserColumnWrap
          data-uxc="obfuscated"
          color={color}
          picture={picture}
          src={picture}
          size={size}
          shape={shape}
          onError={handleImageError}
          alt=""
          className={className}
        >
          <TextWrapper>{textCapital}</TextWrapper>
        </UserColumnWrap>
      )}
      {!imageError && (
        <UserColumnWrap
          data-uxc="obfuscated"
          picture={picture}
          color={color}
          src={picture}
          size={size}
          shape={shape}
          onError={handleImageError}
          crossOrigin='use-credentials'
          alt=""
          className={className}
        >
          <TextWrapper>{textCapital}</TextWrapper>
        </UserColumnWrap>
      )}
    </>
  );
};

export default UserImageInfo;
