const FormItem = Form.Item;

const AppAddModalForm = ({
  menuBar,
  visibleCreateAppModal,
  organizationId,
  displayAppListPopover,
}) => {
  const [form] = Form.useForm();

  const { currentOrgReducer, profileReducer: profile } = useSelector(
    (state) => state
  );
  const { orgId, organizationName, planFeature } = currentOrgReducer;

  const queryClient = useQueryClient();
  const [modalVisible, setModalVisible] = useState(false);
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const [visibleForbiddenModal, setvisibleForbiddenModal] = useState(false);
  const [formData, setFormData] = useState();
  const inputRef = useRef(null);
  const dispatch = useDispatch();

  const newProfile = queryClient.getQueryData(`profileInfo`);
  const roleQueryKey = `roles_permission`;
  const IS_UAE_REGION_DISABLED = true;
  const regionSelectFeatureFlag = !!planFeature?.mriFeature;
  const appList = useFetchAppListById(orgId);
  const firstAppRegion = appList?.data?.[0]?.region || "US"
  //  BE sends display name instead of region key so adding mapper
  const firstAppRegionKey = {
    "US": "us",
    "EU": "eu",
    "UAE": "ae"
  }[firstAppRegion] || "us"
  const defaultRegion = regionSelectFeatureFlag ? 'us' : firstAppRegionKey;
  const storageValue = Form.useWatch('region', form);
  const defaultStorageRegionLabel = {
    'us': 'United States',
    'eu': 'European Union',
    'ae': 'United Arab Emirates'
  }[(defaultRegion)]

  useEffect(() => {
    form.setFieldsValue({ region: defaultRegion });
    inputRef?.current?.focus();
  }, [form, defaultRegion, modalVisible]);

  const handleStorageRegionClick = React.useCallback(
    (region) => () => {
      form.setFieldsValue({ region });
    },
    [form]
  );

  const { data: definedRoles } = useFetchRolesAndPermission(roleQueryKey);
  const { refetch: addApp } = useCreateApp(formData, orgId);

  const handleDestroyClose = () => {
    form.resetFields();
  };

  const onFinish = async (values) => {
    setLoading(true);
    const data = {
      ...values,
      orgId: organizationId || orgId,
      notifyEmail: true,
      appCreatedFrom: 'dashboard',
    };
    setFormData(data);
  };

  const handleUpdateProfile = () => {
    queryClient.setQueryData(`profileInfo`, profile);
  };

  const handleCancel = () => {
    setModalVisible(false);
    setFormData();
    form.resetFields();
  };

  const handleModalOpen = () => {
    setModalVisible(true);
    displayAppListPopover && displayAppListPopover(false);
  };

  const handleAddApp = () => {
    addApp()
      .then(async (response) => {
        setLoading(false);
        if (response?.data?.success) {
          message.success(response?.data?.message);
          queryClient.invalidateQueries(
            `total_apps_${organizationId || orgId}`
          );
          queryClient.invalidateQueries(`teamList${organizationId || orgId}`);
          queryClient.invalidateQueries(`appList_${organizationId || orgId}`);
          /* queryClient.setQueryData(queryKey, (oldData) => {
          const newData = [...oldData, response?.data?.app];
          return newData;
        }); */
          dispatch(getUser());
          await dispatch(getAppDropdown());
          const appId = response?.data?.data['_id'];
          dispatch(
            trackPageViews(null, {
              eventName: 'wa_create_app',
              eventProperty: {
                email: profile?.email || '',
                appId,
                appName: formData?.name || '',
                appType: formData?.appType || 'mobile',
                region: formData?.region || '',
              },
            })
          );
          handleCancel();
          router.push(
            `/integration?parentType=integration&appId=${appId}`,
            `/integration?appId=${appId}`
          );
        }
        if (response?.data?.error?.status === 403) {
          setvisibleForbiddenModal(true);
          form.resetFields();
          setModalVisible(false);
          return;
        }
        if (response?.data?.error?.message?.includes('upgrade your account')) {
          dispatch(
            changeCommonValue(
              'isVisible_custom_popup',
              true,
              ReactHtmlParser(response?.data?.error?.message)
            )
          );
          setModalVisible(false);
          return;
        }
        if (response?.data?.error) {
          const error = response?.data?.error;
          if (!error) {
            message.error("Something went wrong while creating app.")
            return;
          }
          message.error(
              // adding error.name to catch app name related errors
            error.message || error.detail || error.name
          );
        }
      })
      .finally(() => setModalVisible(false));
  };
  const validatePermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, definedRoles, orgId]
  );

  useEffect(() => {
    formData && handleAddApp();
  }, [formData]);

  useEffect(() => {
    const timer = setTimeout(() => {
      modalVisible && inputRef?.current && inputRef?.current.focus();
    }, 500);
    return () => {
      clearTimeout(timer);
    };
  }, [modalVisible, inputRef?.current]);

  useEffect(() => {
    if (visibleCreateAppModal) {
      setModalVisible(visibleCreateAppModal);
    }
  }, [visibleCreateAppModal]);

  useEffect(() => {
    handleUpdateProfile();
  }, [profile]);

  const nameValidator = {
    validator(_, value) {
      if (value === undefined || value === '') {
        return Promise.resolve();
      }
      if (!validateInputName(value)) {
        return Promise.resolve();
      }
      return Promise.reject(new Error(validateInputName(value)));
    },
  };
  const handleAppTypeClick = useCallback(
    (appType) => () => {
      form.setFieldsValue({ appType });
    },
    [form]
  );

  return (
    <MainAppForm>
      {visibleCreateAppModal === undefined &&
        validatePermission(['app.create']) &&
        (menuBar ? (
          <AddAppMenuButtonWrap
            onClick={() => handleModalOpen()}
            data-intercom-target="Add app"
          >
            Create new app
            <AddCircleIcon />
          </AddAppMenuButtonWrap>
        ) : (
          <AddAppMenuButtonWrap
            onClick={() => handleModalOpen()}
            data-intercom-target="Add app"
            blueBG
          >
            Add app
            <AddCircleIcon />
          </AddAppMenuButtonWrap>
        ))}
      <ModalWrap
        visible={modalVisible}
        onCancel={handleCancel}
        closable={false}
        destroyOnClose={handleDestroyClose}
        footer={[null]}
      >
        <FormWrapper form={form} onFinish={onFinish} requiredMark={false}>
          <>
            <ModalHeaderWrap>
              <TextTitle>Create new app</TextTitle>
            </ModalHeaderWrap>
            <TextWrapper>
              This app will be a part of the
              <b>
                {'  '}
                {organizationName}
              </b>{' '}
              organization and fully accessible to the Organization Owner and
              Managers.
            </TextWrapper>
            <TextTitleWrapper>App name</TextTitleWrapper>
            <FormItem
              name="name"
              rules={[
                {
                  whitespace: true,
                  required: true,
                  message: 'Please input your app name',
                },
                nameValidator,
              ]}
              initialValues={{
                region: defaultRegion,
              }}
            >
              <InputWrap
                ref={inputRef}
                placeholder="Enter a name for your new app"
              />
            </FormItem>
            <TextTitleWrapper>Select a platform to integrate</TextTitleWrapper>
            <FormItem name="appType" initialValue="mobile">
              <RadioGroupItem>
                <Radio value="mobile">
                  <RadioItemButton
                    type="button"
                    onClick={handleAppTypeClick('mobile')}
                  >
                    <img src="/static/mobile-app.svg" alt="Mobile App" />
                    <span>Mobile App</span>
                  </RadioItemButton>
                </Radio>
                <Radio value="web">
                  <RadioItemButton
                    type="button"
                    onClick={handleAppTypeClick('web')}
                  >
                    <img src="/static/web-app.svg" alt="Web App" />
                    <span>Web App</span>
                  </RadioItemButton>
                </Radio>
              </RadioGroupItem>
            </FormItem>
            <InputWrapper>
              <Label>Select data storage region</Label>
              <FormItem
                shouldUpdate
                name="region"
                rules={[
                  {
                    required: true,
                    message: 'Please select your region.',
                  },
                ]}
              >
                <RadioGroupItem>
                  <Radio
                    value="us"
                    disabled={!regionSelectFeatureFlag || loading}
                    checked={storageValue === 'us'}
                    Multi-Region-Preference
                  >
                    <RadioItemButton
                      type="button"
                      onClick={handleStorageRegionClick('us')}
                      disabled={!regionSelectFeatureFlag || loading}
                      data-checked={storageValue === 'us'}
                    >
                      <USIcon />
                      <span>US</span>
                    </RadioItemButton>
                  </Radio>
                  <Radio
                    value="eu"
                    disabled={!regionSelectFeatureFlag || loading}
                    checked={storageValue === 'eu'}
                    Multi-Region-Preference
                  >
                    <RadioItemButton
                      type="button"
                      onClick={handleStorageRegionClick('eu')}
                      disabled={!regionSelectFeatureFlag || loading}
                      data-checked={storageValue === 'eu'}
                    >
                      <EUIcon />
                      <span>EU</span>
                    </RadioItemButton>
                  </Radio>
                  <Tooltip
                    title={IS_UAE_REGION_DISABLED ? "UAE region is temporarily unavailable." : undefined}
                  >
                    <span style={{ display: 'inline-block' }}>
                      <Radio
                        value="ae"
                        disabled={!regionSelectFeatureFlag || loading || IS_UAE_REGION_DISABLED}
                        checked={storageValue === 'ae'}
                        Multi-Region-Preference
                        style={IS_UAE_REGION_DISABLED ? { pointerEvents: 'none' } : undefined}
                      >
                        <RadioItemButton
                          type="button"
                          onClick={IS_UAE_REGION_DISABLED ? undefined : handleStorageRegionClick('ae')}
                          disabled={!regionSelectFeatureFlag || loading || IS_UAE_REGION_DISABLED}
                          data-checked={storageValue === 'ae'}
                          style={IS_UAE_REGION_DISABLED ? { opacity: 0.5, cursor: 'not-allowed' } : undefined}
                        >
                          <AEIcon />
                          <span>UAE</span>
                        </RadioItemButton>
                      </Radio>
                    </span>
                  </Tooltip>
                </RadioGroupItem>
              </FormItem>
            </InputWrapper>
            {!regionSelectFeatureFlag && (
              <InfoBox
                variant="gray"
                noMarginBottom
                text={
                  <>
                    Your default data storage is currently in the{' '}
                    {defaultStorageRegionLabel}, and your current plan does not
                    include support for storage across multiple locations. If
                    you require this feature, please
                    <InlineButton
                      onClick={() => showIntercom()}
                      data-intercom-target="Multi-region-contact"
                      data-multi-region-preference={defaultRegion}
                      type="button"
                    >
                      contact our customer support team
                    </InlineButton>
                  </>
                }
              />
            )}
          </>
          <FormButton>
            <SecondaryModalButton
              key="link"
              type="secondary"
              onClick={() => handleCancel()}
            >
              Cancel
            </SecondaryModalButton>

            <PrimaryModalButton
              key="submit"
              htmlType="submit"
              type="primary"
              loading={loading}
              disabled={loading}
            >
              Create
            </PrimaryModalButton>
          </FormButton>
        </FormWrapper>
      </ModalWrap>
      {visibleForbiddenModal && (
        <ForbiddenModal
          visibleForbiddenModal={visibleForbiddenModal}
          setVisibleForbiddenModal={setvisibleForbiddenModal}
        />
      )}
    </MainAppForm>
  );
};

export default AppAddModalForm;
